-- ---------------------------------------------------------------------
-- Shared trigger: keep updated_at current on every UPDATE
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- 1. roles
-- ---------------------------------------------------------------------
CREATE TABLE roles (
  id            SMALLSERIAL PRIMARY KEY,
  name          VARCHAR(30)  NOT NULL UNIQUE
                CHECK (name IN ('super_admin', 'inspector', 'ward_user')),
  display_name  VARCHAR(60)  NOT NULL,
  description   TEXT,
  created_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- 2. users
-- token_version is embedded in every JWT. Incrementing it (logout,
-- deactivation, password change, role change) invalidates old tokens.
-- ---------------------------------------------------------------------
CREATE TABLE users (
  id             SERIAL PRIMARY KEY,
  full_name      VARCHAR(120) NOT NULL,
  username       VARCHAR(50)  NOT NULL,
  email          VARCHAR(150),
  phone          VARCHAR(20),
  designation    VARCHAR(100),
  password_hash  VARCHAR(255) NOT NULL,
  role_id        SMALLINT     NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,
  is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
  token_version  INTEGER      NOT NULL DEFAULT 0,
  last_login_at  TIMESTAMPTZ,
  created_by     INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  CONSTRAINT users_username_format CHECK (username ~ '^[a-z0-9._-]{3,50}$')
);
CREATE UNIQUE INDEX users_username_uq ON users (LOWER(username));
CREATE UNIQUE INDEX users_email_uq    ON users (LOWER(email)) WHERE email IS NOT NULL;
CREATE INDEX users_role_idx           ON users (role_id);

-- ---------------------------------------------------------------------
-- 3. wards
-- ---------------------------------------------------------------------
CREATE TABLE wards (
  id                SERIAL PRIMARY KEY,
  ward_number       SMALLINT     NOT NULL UNIQUE CHECK (ward_number BETWEEN 1 AND 99),
  office_name       VARCHAR(150) NOT NULL,
  address           VARCHAR(255),
  chairperson_name  VARCHAR(120),
  secretary_name    VARCHAR(120),
  contact_number    VARCHAR(30),
  email             VARCHAR(150),
  remarks           TEXT,
  is_active         BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- 4. user_wards  (inspectors and ward users -> wards)
-- ---------------------------------------------------------------------
CREATE TABLE user_wards (
  user_id      INTEGER     NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  ward_id      INTEGER     NOT NULL REFERENCES wards(id) ON DELETE CASCADE,
  assigned_by  INTEGER     REFERENCES users(id) ON DELETE SET NULL,
  assigned_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, ward_id)
);
CREATE INDEX user_wards_ward_idx ON user_wards (ward_id);

-- ---------------------------------------------------------------------
-- 5. equipment_categories
-- group_name     : the A–G grouping (e.g. "CCTV Surveillance")
-- type_options   : default sub-types (e.g. {Laser, Inkjet})
-- checklist_group: which technical checklist applies
-- ---------------------------------------------------------------------
CREATE TABLE equipment_categories (
  id               SERIAL PRIMARY KEY,
  code             VARCHAR(30)  NOT NULL UNIQUE,
  name             VARCHAR(120) NOT NULL UNIQUE,
  group_name       VARCHAR(80)  NOT NULL,
  type_options     TEXT[]       NOT NULL DEFAULT '{}',
  checklist_group  VARCHAR(30)
                   CHECK (checklist_group IN ('computer','printer','biometric','cctv',
                                              'networking','ups','presentation')),
  description      TEXT,
  sort_order       SMALLINT     NOT NULL DEFAULT 0,
  is_active        BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX equipment_categories_group_idx ON equipment_categories (group_name, sort_order);

-- ---------------------------------------------------------------------
-- 6. equipment
-- current_condition is NULL until the first submitted inspection.
-- ---------------------------------------------------------------------
CREATE TABLE equipment (
  id                     SERIAL PRIMARY KEY,
  asset_id               VARCHAR(50)  NOT NULL,
  ward_id                INTEGER      NOT NULL REFERENCES wards(id) ON DELETE RESTRICT,
  category_id            INTEGER      NOT NULL REFERENCES equipment_categories(id) ON DELETE RESTRICT,
  name                   VARCHAR(150) NOT NULL,
  equipment_type         VARCHAR(60),
  brand                  VARCHAR(80),
  model                  VARCHAR(80),
  serial_number          VARCHAR(100),
  installation_location  VARCHAR(150),
  quantity               INTEGER      NOT NULL DEFAULT 1 CHECK (quantity > 0),
  purchase_date          DATE,
  warranty_expiry        DATE,
  current_condition      VARCHAR(20)
                         CHECK (current_condition IN ('good','partial','not_operational','damaged')),
  condition_updated_at   TIMESTAMPTZ,
  last_inspection_id     INTEGER,      -- FK added after inspections table exists
  status                 VARCHAR(20)  NOT NULL DEFAULT 'active'
                         CHECK (status IN ('active','replaced','disposed')),
  remarks                TEXT,
  created_by             INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX equipment_asset_id_uq ON equipment (UPPER(asset_id));
CREATE UNIQUE INDEX equipment_serial_uq   ON equipment (category_id, UPPER(serial_number))
  WHERE serial_number IS NOT NULL AND serial_number <> '';
CREATE INDEX equipment_ward_idx        ON equipment (ward_id);
CREATE INDEX equipment_category_idx    ON equipment (category_id);
CREATE INDEX equipment_condition_idx   ON equipment (current_condition);
CREATE INDEX equipment_name_idx        ON equipment (LOWER(name));
CREATE INDEX equipment_serial_idx      ON equipment (UPPER(serial_number));

-- ---------------------------------------------------------------------
-- 7. inspections
-- Every inspection is its own row: history is never overwritten.
-- Drafts may be saved before the equipment record is chosen/created.
-- ---------------------------------------------------------------------
CREATE TABLE inspections (
  id                       SERIAL PRIMARY KEY,
  inspection_code          VARCHAR(20)  UNIQUE,          -- set by trigger: INS-2026-000001
  ward_id                  INTEGER      NOT NULL REFERENCES wards(id) ON DELETE RESTRICT,
  equipment_id             INTEGER      REFERENCES equipment(id) ON DELETE RESTRICT,
  category_id              INTEGER      REFERENCES equipment_categories(id) ON DELETE RESTRICT,
  inspector_id             INTEGER      NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  inspection_date          DATE         NOT NULL DEFAULT CURRENT_DATE,
  inspection_type          VARCHAR(20)  NOT NULL DEFAULT 'routine'
                           CHECK (inspection_type IN ('initial','routine','follow_up')),
  condition                VARCHAR(20)
                           CHECK (condition IN ('good','partial','not_operational','damaged')),
  problem_description      TEXT,
  technical_fault          TEXT,
  repair_required          BOOLEAN,
  required_repair_work     TEXT,
  required_spare_parts     TEXT,
  estimated_repair_cost    NUMERIC(12,2) CHECK (estimated_repair_cost >= 0),
  recommended_actions      TEXT[]       NOT NULL DEFAULT '{}'
                           CHECK (recommended_actions <@ ARRAY[
                             'no_action','general_maintenance','hardware_repair','software_update',
                             'network_configuration','cctv_configuration','biometric_configuration',
                             'electrical_repair','spare_parts_replacement','device_replacement',
                             'new_purchase','further_assessment']::TEXT[]),
  recommendation           TEXT,
  replacement_reason       TEXT,
  technical_justification  TEXT,
  inspector_remarks        TEXT,
  status                   VARCHAR(20)  NOT NULL DEFAULT 'draft'
                           CHECK (status IN ('draft','submitted')),
  submitted_at             TIMESTAMPTZ,
  created_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

  -- A submitted inspection must be complete
  CONSTRAINT inspections_submitted_complete CHECK (
    status = 'draft' OR (
      equipment_id IS NOT NULL AND condition IS NOT NULL AND submitted_at IS NOT NULL
    )
  ),
  -- Replacement recommendations need a reason and justification
  CONSTRAINT inspections_replacement_reason CHECK (
    status = 'draft'
    OR NOT ('device_replacement' = ANY (recommended_actions))
    OR (COALESCE(TRIM(replacement_reason), '') <> ''
        AND COALESCE(TRIM(technical_justification), '') <> '')
  )
);
CREATE INDEX inspections_ward_idx       ON inspections (ward_id);
CREATE INDEX inspections_equipment_idx  ON inspections (equipment_id, inspection_date DESC);
CREATE INDEX inspections_inspector_idx  ON inspections (inspector_id);
CREATE INDEX inspections_date_idx       ON inspections (inspection_date);
CREATE INDEX inspections_status_idx     ON inspections (status);
CREATE INDEX inspections_condition_idx  ON inspections (condition);

ALTER TABLE equipment
  ADD CONSTRAINT equipment_last_inspection_fk
  FOREIGN KEY (last_inspection_id) REFERENCES inspections(id) ON DELETE SET NULL;

-- Human-readable code, e.g. INS-2026-000042
CREATE OR REPLACE FUNCTION set_inspection_code()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.inspection_code IS NULL THEN
    NEW.inspection_code := 'INS-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(NEW.id::TEXT, 6, '0');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- 8. inspection_checklist_items  (master list per checklist_group)
-- ---------------------------------------------------------------------
CREATE TABLE inspection_checklist_items (
  id               SERIAL PRIMARY KEY,
  checklist_group  VARCHAR(30)  NOT NULL
                   CHECK (checklist_group IN ('computer','printer','biometric','cctv',
                                              'networking','ups','presentation')),
  label            VARCHAR(120) NOT NULL,
  sort_order       SMALLINT     NOT NULL DEFAULT 0,
  is_active        BOOLEAN      NOT NULL DEFAULT TRUE,
  created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  UNIQUE (checklist_group, label)
);

-- ---------------------------------------------------------------------
-- 9. inspection_checklist_results
-- ---------------------------------------------------------------------
CREATE TABLE inspection_checklist_results (
  id                 SERIAL PRIMARY KEY,
  inspection_id      INTEGER     NOT NULL REFERENCES inspections(id) ON DELETE CASCADE,
  checklist_item_id  INTEGER     NOT NULL REFERENCES inspection_checklist_items(id) ON DELETE RESTRICT,
  result             VARCHAR(20) NOT NULL CHECK (result IN ('good','problem','not_applicable')),
  remarks            TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (inspection_id, checklist_item_id)
);

-- ---------------------------------------------------------------------
-- 10. inspection_photos  (files on disk; only path + metadata here)
-- ---------------------------------------------------------------------
CREATE TABLE inspection_photos (
  id             SERIAL PRIMARY KEY,
  inspection_id  INTEGER      NOT NULL REFERENCES inspections(id) ON DELETE CASCADE,
  file_path      VARCHAR(500) NOT NULL UNIQUE,
  original_name  VARCHAR(255),
  mime_type      VARCHAR(50)  NOT NULL
                 CHECK (mime_type IN ('image/jpeg','image/png','image/webp')),
  size_bytes     INTEGER      NOT NULL CHECK (size_bytes > 0),
  photo_type     VARCHAR(30)  NOT NULL DEFAULT 'general'
                 CHECK (photo_type IN ('general','front_view','serial_number','damage',
                                       'installation','network_rack','cable_management')),
  caption        VARCHAR(255),
  uploaded_by    INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX inspection_photos_inspection_idx ON inspection_photos (inspection_id);

-- ---------------------------------------------------------------------
-- 11. maintenance
-- source = 'inspection' (created from an inspection) or
--          'ward_report' (a ward office user reported a fault)
-- ---------------------------------------------------------------------
CREATE TABLE maintenance (
  id                SERIAL PRIMARY KEY,
  maintenance_code  VARCHAR(20)  UNIQUE,                 -- set by trigger: MNT-2026-000001
  equipment_id      INTEGER      NOT NULL REFERENCES equipment(id) ON DELETE RESTRICT,
  ward_id           INTEGER      NOT NULL REFERENCES wards(id) ON DELETE RESTRICT,
  inspection_id     INTEGER      REFERENCES inspections(id) ON DELETE SET NULL,
  source            VARCHAR(20)  NOT NULL DEFAULT 'inspection'
                    CHECK (source IN ('inspection','ward_report','manual')),
  reported_problem  TEXT         NOT NULL,
  required_repair   TEXT,
  technician_id     INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  technician_name   VARCHAR(120),
  maintenance_date  DATE,
  repair_cost       NUMERIC(12,2) CHECK (repair_cost >= 0),
  completion_date   DATE,
  status            VARCHAR(20)  NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','under_assessment','approved','in_progress',
                                      'completed','not_repairable','cancelled')),
  approved_by       INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  approved_at       TIMESTAMPTZ,
  remarks           TEXT,
  reported_by       INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  CONSTRAINT maintenance_completion_after_start CHECK (
    completion_date IS NULL OR maintenance_date IS NULL OR completion_date >= maintenance_date
  )
);
CREATE INDEX maintenance_equipment_idx ON maintenance (equipment_id, created_at DESC);
CREATE INDEX maintenance_ward_idx      ON maintenance (ward_id);
CREATE INDEX maintenance_status_idx    ON maintenance (status);

CREATE OR REPLACE FUNCTION set_maintenance_code()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.maintenance_code IS NULL THEN
    NEW.maintenance_code := 'MNT-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(NEW.id::TEXT, 6, '0');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- Maintenance before/after photographs (supporting table for #11)
-- ---------------------------------------------------------------------
CREATE TABLE maintenance_photos (
  id              SERIAL PRIMARY KEY,
  maintenance_id  INTEGER      NOT NULL REFERENCES maintenance(id) ON DELETE CASCADE,
  stage           VARCHAR(10)  NOT NULL CHECK (stage IN ('before','after')),
  file_path       VARCHAR(500) NOT NULL UNIQUE,
  original_name   VARCHAR(255),
  mime_type       VARCHAR(50)  NOT NULL
                  CHECK (mime_type IN ('image/jpeg','image/png','image/webp')),
  size_bytes      INTEGER      NOT NULL CHECK (size_bytes > 0),
  caption         VARCHAR(255),
  uploaded_by     INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);
CREATE INDEX maintenance_photos_maintenance_idx ON maintenance_photos (maintenance_id);

-- ---------------------------------------------------------------------
-- 12. maintenance_spare_parts
-- ---------------------------------------------------------------------
CREATE TABLE maintenance_spare_parts (
  id              SERIAL PRIMARY KEY,
  maintenance_id  INTEGER       NOT NULL REFERENCES maintenance(id) ON DELETE CASCADE,
  part_name       VARCHAR(150)  NOT NULL,
  quantity        INTEGER       NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit_cost       NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK (unit_cost >= 0),
  total_cost      NUMERIC(14,2) GENERATED ALWAYS AS (quantity * unit_cost) STORED,
  remarks         TEXT,
  created_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW()
);
CREATE INDEX maintenance_spare_parts_maintenance_idx ON maintenance_spare_parts (maintenance_id);

-- ---------------------------------------------------------------------
-- 13. replacement_requests
-- Approving a request never marks the device replaced automatically;
-- equipment.status changes only when a Super Admin records delivery.
-- ---------------------------------------------------------------------
CREATE TABLE replacement_requests (
  id                        SERIAL PRIMARY KEY,
  request_code              VARCHAR(20)   UNIQUE,         -- set by trigger: RPL-2026-000001
  equipment_id              INTEGER       NOT NULL REFERENCES equipment(id) ON DELETE RESTRICT,
  ward_id                   INTEGER       NOT NULL REFERENCES wards(id) ON DELETE RESTRICT,
  inspection_id             INTEGER       REFERENCES inspections(id) ON DELETE SET NULL,
  current_condition         VARCHAR(20)
                            CHECK (current_condition IN ('good','partial','not_operational','damaged')),
  reason                    TEXT          NOT NULL,
  technical_recommendation  TEXT          NOT NULL,
  estimated_cost            NUMERIC(12,2) CHECK (estimated_cost >= 0),
  status                    VARCHAR(20)   NOT NULL DEFAULT 'pending'
                            CHECK (status IN ('pending','approved','rejected','purchased','delivered')),
  requested_by              INTEGER       REFERENCES users(id) ON DELETE SET NULL,
  reviewed_by               INTEGER       REFERENCES users(id) ON DELETE SET NULL,
  reviewed_at               TIMESTAMPTZ,
  review_remarks            TEXT,
  remarks                   TEXT,
  created_at                TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
  updated_at                TIMESTAMPTZ   NOT NULL DEFAULT NOW()
);
CREATE INDEX replacement_requests_equipment_idx ON replacement_requests (equipment_id);
CREATE INDEX replacement_requests_ward_idx      ON replacement_requests (ward_id);
CREATE INDEX replacement_requests_status_idx    ON replacement_requests (status);

CREATE OR REPLACE FUNCTION set_replacement_code()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.request_code IS NULL THEN
    NEW.request_code := 'RPL-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(NEW.id::TEXT, 6, '0');
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- 14. audit_logs
-- ---------------------------------------------------------------------
CREATE TABLE audit_logs (
  id           BIGSERIAL PRIMARY KEY,
  user_id      INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  action       VARCHAR(60)  NOT NULL,
  entity_type  VARCHAR(40),
  entity_id    VARCHAR(40),
  details      JSONB        NOT NULL DEFAULT '{}'::JSONB,
  ip_address   VARCHAR(64),
