);
CREATE INDEX audit_logs_user_idx    ON audit_logs (user_id, created_at DESC);
CREATE INDEX audit_logs_entity_idx  ON audit_logs (entity_type, entity_id);
CREATE INDEX audit_logs_created_idx ON audit_logs (created_at DESC);

-- ---------------------------------------------------------------------
-- System settings (key/value, managed by Super Admin)
-- ---------------------------------------------------------------------
CREATE TABLE system_settings (
  key          VARCHAR(80)  PRIMARY KEY,
  value        TEXT,
  description  TEXT,
  updated_by   INTEGER      REFERENCES users(id) ON DELETE SET NULL,
  created_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- ---------------------------------------------------------------------
-- Triggers
-- ---------------------------------------------------------------------
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'roles','users','wards','equipment_categories','equipment','inspections',
    'inspection_checklist_items','inspection_checklist_results','inspection_photos',
    'maintenance','maintenance_photos','maintenance_spare_parts','replacement_requests',
    'system_settings'
  ] LOOP
    EXECUTE format(
      'CREATE TRIGGER %I_set_updated_at BEFORE UPDATE ON %I
       FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t, t);
  END LOOP;
END $$;

CREATE TRIGGER inspections_set_code BEFORE INSERT ON inspections
  FOR EACH ROW EXECUTE FUNCTION set_inspection_code();
CREATE TRIGGER maintenance_set_code BEFORE INSERT ON maintenance
  FOR EACH ROW EXECUTE FUNCTION set_maintenance_code();
CREATE TRIGGER replacement_requests_set_code BEFORE INSERT ON replacement_requests
  FOR EACH ROW EXECUTE FUNCTION set_replacement_code();

